from pathlib import Path
import json,html
root=Path('.')
(root/'compositions').mkdir(exist_ok=True)
style='''@font-face{font-family:Noto Sans;src:url('assets/fonts/NotoSans-Regular.ttf')}*{box-sizing:border-box;margin:0}#root{position:absolute;inset:0;overflow:hidden;background:#f6f7fb;color:#171a1f;font-family:Noto Sans,sans-serif}.scene-title{position:absolute;left:128px;top:70px;right:100px;font-size:64px;line-height:1.22;letter-spacing:-2.5px;font-weight:400;height:100px}.window{position:absolute;left:96px;top:222px;width:1728px;height:700px;overflow:hidden;border-radius:20px;background:#f6f7fb}.world{position:absolute;left:0;top:0;width:1040px;height:760px;transform-origin:0 0}.world video,.world img{position:absolute;left:0;top:0;width:1040px;height:760px;object-fit:fill}.note{position:absolute;left:128px;bottom:108px;font-size:28px;color:#626976;line-height:1.4}.paper{position:absolute;left:800px;top:10px;width:900px;height:auto;box-shadow:0 12px 50px #253c7118}.end-wordmark{position:absolute;left:340px;top:302px;display:flex;align-items:center;gap:32px}.end-wordmark img{width:96px;height:96px}.end-wordmark h1{font-size:72px;letter-spacing:-3px;font-weight:400}.end-wordmark h1:after{content:'';display:inline-block;width:12px;height:12px;background:#d52546;border-radius:50%;margin-left:10px}.end-line{position:absolute;left:340px;top:455px;font-size:43px;letter-spacing:-1px}.end-url{position:absolute;left:340px;top:548px;font-size:38px;color:#1d5bff}.end-demo{position:absolute;left:340px;top:662px;font-size:28px;color:#626976}.end-credit{position:absolute;left:340px;top:832px;font-size:28px;color:#626976;line-height:1.6}'''
scenes=[]
def emit(name,start,duration,title,body,script,note=''):
    variables=[{'id':'headline','type':'string','label':'Tytuł','default':title}]
    contents=f'''<template>\n<style>{style}</style>\n<div id="root" data-composition-id="{name}" data-width="1920" data-height="1080" data-composition-variables='{json.dumps(variables,ensure_ascii=False)}'>\n<h1 id="title" class="clip scene-title" data-start="0" data-duration="{duration}" data-var-text="headline">{html.escape(title)}</h1>\n{body}\n'''
    if note:contents+=f'<p id="note" class="clip note" data-start="0" data-duration="{duration}">{html.escape(note)}</p>\n'
    contents+=f'''</div>\n<script>const tl=gsap.timeline({{paused:true}});{script}\nwindow.__timelines['{name}']=tl;</script>\n</template>'''
    (root/'compositions'/f'{name}.html').write_text(contents)
    scenes.append((name,start,duration))
# The camera law adapts the installed ui-focus-zoom primitive: a single world transform,
# position + scale are seekable GSAP values. No halo, drift or skeleton UI.
emit('result',0,3,'Jedna sprawa. Załatwiona.', '<div class="window" data-layout-allow-overflow><div class="world"><img id="result-image" class="clip" data-start="0" data-duration="3" style="height:435px;object-fit:contain" src="assets/screens/finished-card.png" alt="Załatwiona sprawa narodzin dziecka z dokumentami"></div></div>',"tl.set('.world',{x:32,y:0,scale:1.6});tl.fromTo('.world',{x:60,scale:1.55},{x:32,scale:1.6,duration:.65,ease:'power2.out'});",'Narodziny dziecka · fragment demonstracji')
def footage(name,start,duration,title,mediaStart,rate,cam0,cam1=None,moveAt=0,moveDur=.6,note='Montaż klikalnego prototypu · fikcyjne dane'):
    body=f'''<div class="window" data-layout-allow-overflow><div class="world"><video id="screen" class="clip" src="assets/{name}.mp4" data-start="0" data-duration="{duration}" muted playsinline></video></div></div>'''
    script=f"tl.set('.world',{json.dumps(cam0)});"
    if cam1:script+=f"tl.to('.world',{{...{json.dumps(cam1)},duration:{moveDur},ease:'power2.inOut'}},{moveAt});"
    emit(name,start,duration,title,body,script,note)
footage('start',3,4,'Zaczynasz od swojej sprawy',2,1.05,{'x':340,'y':0,'scale':1.0},{'x':-60,'y':-650,'scale':1.78},1.65,.65)
footage('data',7,8,'Dane podajesz raz',6.2,1.3,{'x':-60,'y':-650,'scale':1.78})
footage('usc',15,8,'USC rejestruje urodzenie',16.3,1.0,{'x':-60,'y':-650,'scale':1.78})
footage('zus',23,9,'Wynik trafia do ZUS',25.2,.75,{'x':-60,'y':-130,'scale':1.78},{'x':-60,'y':-650,'scale':1.78},3.4,.6)
thread='<div class="window" data-layout-allow-overflow><div class="world"><video id="screen" class="clip" src="assets/thread.mp4" data-start="0" data-duration="5" muted playsinline></video></div></div>'
emit('thread',32,5,'Możesz zajrzeć w pracę agenta',thread,"tl.set('.world',{x:-50,y:-30,scale:1.76});tl.to('.world',{y:-390,duration:.65,ease:'power2.inOut'},2.1);",'Podgląd narzędzi i wyników wybranego agenta')
docs='<div class="window" data-layout-allow-overflow><div class="world"><img id="case-view" class="clip" src="assets/screens/overview.png" data-start="0" data-duration="7" alt="Gotowa sprawa i dokumenty do pobrania"></div><img id="paper" data-hold="Czytanie przykładowego dokumentu" class="clip paper" src="assets/screens/document.png" data-start="2.8" data-duration="4.2" alt="Rzeczywisty przykładowy PDF wygenerowany przez prototyp"></div>'
emit('documents',37,7,'Sprawa gotowa. Dokumenty też.',docs,"tl.set('.world',{x:-15,y:-150,scale:1.64});tl.to('.world',{x:-750,duration:.65,ease:'power2.inOut'},2.8);tl.fromTo('#paper',{x:950,rotation:0},{x:0,duration:.65,ease:'power3.out'},2.8);",'Przykładowe formularze i potwierdzenia PDF do pobrania')
# End card is a built lockup using the original project mark.
endbody='''<div id="brand" class="clip end-wordmark" data-start="0" data-duration="4"><img src="assets/brand.svg" alt="Znak Ogarniacza"><h1>mObywatel — Ogarniacz</h1></div><p id="end-line" class="clip end-line" data-start="0.15" data-duration="3.85">Ty wybierasz cel. Agenci ogarniają resztę.</p><p id="end-url" class="clip end-url" data-start="0.4" data-duration="3.6">mobywatel-ogarniacz.pages.dev</p><p id="end-demo" class="clip end-demo" data-start="0.4" data-duration="3.6">Nieoficjalny prototyp · symulacja działań · fikcyjne dane</p><p id="credit" class="clip end-credit" data-start="0" data-duration="4">Muzyka: „Inspired” — Kevin MacLeod (incompetech.com)<br>CC BY 4.0 · creativecommons.org/licenses/by/4.0/</p>'''
emit('outro',44,4,'',endbody,"tl.fromTo('#brand',{clipPath:'inset(0 100% 0 0)'},{clipPath:'inset(0 0% 0 0)',duration:.55,ease:'power3.out'});tl.fromTo('#end-url',{opacity:0},{opacity:1,duration:.3},.4);")
hosts='\n'.join(f'<div id="{n}" class="clip" data-composition-id="{n}" data-composition-src="compositions/{n}.html" data-start="{s}" data-duration="{d}" data-track-index="1" data-track-kind="graphics" data-width="1920" data-height="1080"></div>' for n,s,d in scenes)
root.joinpath('index.html').write_text('''<!doctype html><html lang="pl" data-composition-variables='[{"id":"brand_blue","type":"color","label":"Akcent","default":"#1d5bff"}]'><head><meta charset="UTF-8"><meta name="viewport" content="width=1920,height=1080"><title>mObywatel — Ogarniacz · demo</title><script src="assets/gsap.min.js"></script><style>*{margin:0;box-sizing:border-box}html,body{width:1920px;height:1080px;overflow:hidden;background:#f6f7fb}#root{position:relative;width:1920px;height:1080px}.clip{position:absolute}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="48" data-width="1920" data-height="1080" data-fps="30">'''+hosts+''.join(f'<audio id="click-{i}" class="clip" src="assets/click.mp3" data-start="{t}" data-duration="0.4" data-track-index="3" data-volume="0.22"></audio>' for i,t in enumerate([11.6,15.95,23.9]))+'''<audio id="music" class="clip" src="assets/music.wav" data-start="0" data-duration="48" data-track-index="2" data-volume="0.95"></audio></div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true});</script></body></html>''')
